SELECT p.id AS position_id, w.id, w.symbol, w.side, w.status, w.quantity, w.price_usdt, w.decision_price_usdt, w.execution_price_observed_at, w.executed_at, w.gross_amount_usdt, w.fee_usdt, w.realized_pnl_usdt, w.realized_pnl_percent, w.execution_type, LEFT(w.execution_reason,300) AS exec_reason, w.signal_id, w.execution_key FROM paper_position p JOIN wallet_trade w ON w.symbol = p.symbol AND w.executed_at BETWEEN p.opened_at - INTERVAL 60 SECOND AND p.closed_at + INTERVAL 60 SECOND WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, w.executed_at